// Make text safe to put inside an HTML email
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = (n) => n == null || n === '' ? '-' : '$' + Math.round(Number(n)).toLocaleString('en-US');

// Email text in the customer's language. Add more languages by copying a block.
const TEXT = {
  en: { arrived: 'Just arrived', hello: 'Hello', intro: 'A watch you are looking for has just arrived:', price: 'Price',
        reply: 'Reply to this email to reserve a viewing or ask a question.',
        footer: 'You receive this because you asked to be told about matching watches. Reply STOP to unsubscribe.' },
  ar: { arrived: 'وصلت الآن', hello: 'مرحباً', intro: 'وصلت للتو ساعة تبحث عنها:', price: 'السعر',
        reply: 'رد على هذه الرسالة لحجز موعد معاينة أو لطرح أي سؤال.',
        footer: 'تصلك هذه الرسالة لأنك طلبت إبلاغك بالساعات المطابقة. أرسل STOP لإلغاء الاشتراك.' },
  fr: { arrived: 'Nouvelle arrivée', hello: 'Bonjour', intro: 'Une montre que vous recherchez vient d’arriver :', price: 'Prix',
        reply: 'Répondez à cet e-mail pour réserver une présentation ou poser une question.',
        footer: 'Vous recevez ce message car vous avez demandé à être informé des montres correspondantes. Répondez STOP pour vous désabonner.' },
  de: { arrived: 'Neu eingetroffen', hello: 'Hallo', intro: 'Eine Uhr, die Sie suchen, ist gerade eingetroffen:', price: 'Preis',
        reply: 'Antworten Sie auf diese E-Mail, um einen Besichtigungstermin zu reservieren oder eine Frage zu stellen.',
        footer: 'Sie erhalten diese E-Mail, weil Sie über passende Uhren informiert werden möchten. Antworten Sie STOP zum Abmelden.' },
  zh: { arrived: '新品到货', hello: '您好', intro: '您正在寻找的腕表刚刚到货：', price: '价格',
        reply: '回复此邮件即可预约看表或咨询问题。',
        footer: '您收到此邮件是因为您订阅了匹配腕表通知。回复 STOP 即可退订。' },
};
const d = $json;
const t = TEXT[d.language] || TEXT.en;
const dir = d.language === 'ar' ? 'rtl' : 'ltr';
const title = d.listing_title || `${d.brand} ${d.model || ''} ${d.reference}`;
return {
  json: {
    ...d,
    subject: `${t.arrived}: ${title}`,
    html: `<div dir="${dir}"><p>${t.hello} ${esc(d.name || '')},</p>
<p>${t.intro}</p>
<h3>${esc(title)}</h3>
<p style="white-space:pre-wrap">${esc(d.listing_description || '')}</p>
<p><b>${t.price}: ${money(d.ask_usd)}</b></p>
<p>${t.reply}</p>
<p>${esc(d.business_name)}</p>
<p style="color:#888;font-size:11px">${t.footer}</p></div>`,
  },
};

// When the database query finds nothing, n8n still passes one item: {"success": true}.
// Remove it so the next steps only run for real rows.
return $input.all()
  .map((item, index) => ({ json: item.json, pairedItem: { item: index } }))
  .filter(item => !(Object.keys(item.json).length === 1 && item.json.success === true));

